cd /app && for t in all build/lib/libqs.a build/bin/colstat build/bin/qcalc check install 'check install'; do for i in 1 2 3; do make clean >/dev/null; make -j8 $t DESTDIR=/tmp/st3 >/tmp/o.log 2>&1 || echo FAIL $t $i; done; done; echo done; make clean >/dev/null; make -j8 DEBUG=1 >/dev/null 2>&1 && echo dbg ok; cat > /tmp/t.c <<'EOF'
#include <qs/qs.h>
#include <stdio.h>
int main(void){double v; qs_eval("2^3",&v); printf("%g %s\n",v,QS_VERSION);}
EOF
gcc -I/tmp/stage2/usr/local/include /tmp/t.c /tmp/stage2/usr/local/lib/libqs.a -lm -o /tmp/t && /tmp/t
